begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('d1100000-0000-0000-0000-000000000001','authenticated','authenticated','fiscal-a@example.test','',now(),'{}','{"name":"Fiscal A","company_name":"Fiscal A"}',now(),now()),
('d1100000-0000-0000-0000-000000000002','authenticated','authenticated','fiscal-b@example.test','',now(),'{}','{"name":"Fiscal B","company_name":"Fiscal B"}',now(),now());
select set_config('request.jwt.claims','{"sub":"d1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('fiscal.company',private.current_company_id(),true);
update public.companies set name='QA Fiscal Synthetic',document='11222333000181',street='Rua de Teste',number='1',city='Recife',state='PE',cep='50000000' where id=current_setting('fiscal.company');
insert into public.customers(id,company_id,name,document,address,email) values('fiscal-customer',current_setting('fiscal.company'),'Synthetic fiscal customer','52998224725','{"street":"Rua QA","number":"1","city":"Recife","state":"PE","zip_code":"50000000"}','qa@example.test');
insert into public.products(id,company_id,name,pricing_type,sales_price) values('fiscal-product',current_setting('fiscal.company'),'Synthetic service','unidade',100);
insert into public.orders(id,company_id,customer_id,customer_name,number,status,total_amount,shipping_cost,paid_amount) values('fiscal-order',current_setting('fiscal.company'),'fiscal-customer','Synthetic fiscal customer','QA-FISCAL-1','aguardando_pagamento',100,0,0),('fiscal-order2',current_setting('fiscal.company'),'fiscal-customer','Synthetic fiscal customer','QA-FISCAL-2','aguardando_pagamento',100,0,0);
insert into public.order_items(order_id,product_id,product_name,quantity,unit_price,total_price) values('fiscal-order','fiscal-product','Synthetic service',1,100,100),('fiscal-order2','fiscal-product','Synthetic service',1,100,100);
insert into private.fiscal_qa_orders values('fiscal-order',current_setting('fiscal.company')),('fiscal-order2',current_setting('fiscal.company'));
select ok(private.fiscal_document_valid('11222333000181'),'CNPJ checksum valid');
select ok(private.fiscal_document_valid('52998224725'),'CPF checksum valid');
select ok(not private.fiscal_document_valid('11222333000182'),'wrong CNPJ checksum rejected');
select ok(not private.fiscal_document_valid('52998224724'),'wrong CPF checksum rejected');
select ok(not private.fiscal_document_valid('11111111111'),'repeated digits rejected');
update public.companies set state=null where id=current_setting('fiscal.company');
select ok(private.fiscal_prepare(current_setting('fiscal.company'),'fiscal-order')->'errors' ? 'Endereço fiscal da empresa incompleto.','null issuer UF rejected');
update public.companies set state='PE' where id=current_setting('fiscal.company');
set local role authenticated;
select ok(not has_function_privilege('anon','public.fiscal_command(text,jsonb,uuid)','execute'),'anon cannot issue');
select ok(not has_function_privilege('authenticated','public.fiscal_provider_event(jsonb)','execute'),'browser cannot confirm authorization');
select ok(not has_function_privilege('authenticated','public.fiscal_mock_secret()','execute'),'browser cannot read secret');
select ok(not has_table_privilege('authenticated','public.fiscal_documents','insert'),'browser cannot forge documents');
select ok(not has_table_privilege('authenticated','private.fiscal_qa_orders','insert'),'browser cannot allowlist real orders');
select throws_ok($$select public.fiscal_command('request','{"order_id":"fiscal-order","environment":"production"}',gen_random_uuid())$$,'22023','FISCAL_REAL_EMISSION_REQUIRES_EXPLICIT_AUTHORIZATION','real fiscal issuance blocked');
select ok(jsonb_array_length(public.fiscal_command('prevalidate','{"order_id":"fiscal-order"}',gen_random_uuid())->'errors')>0,'incomplete settings block prevalidation');
select public.fiscal_command('settings','{"data":{"municipal_registration":"QA-IM","municipality_code":"2611606","cnae":"1813099","series":"QA","nature":"Serviço sintético QA","tax_regime":"outro","default_service_code":"QA-TEST"}}',gen_random_uuid());
select public.fiscal_command('customer','{"id":"fiscal-customer","municipality_code":"2611606"}',gen_random_uuid());
select is(jsonb_array_length(public.fiscal_command('prevalidate','{"order_id":"fiscal-order"}',gen_random_uuid())->'errors'),0,'complete canonical data ready for QA');
select set_config('fiscal.fingerprint',public.fiscal_command('prevalidate','{"order_id":"fiscal-order"}',gen_random_uuid())->>'fingerprint',true);
reset role;
update public.orders set total_amount=200 where id='fiscal-order';
set local role authenticated;
select throws_ok(format('select public.fiscal_command(%L,%L::jsonb,gen_random_uuid())','request',jsonb_build_object('order_id','fiscal-order','fingerprint',current_setting('fiscal.fingerprint'))::text),'22023','Fiscal: Dados alterados após a pré-validação. Confira o resumo novamente.','stale preview cannot issue changed amount');
select set_config('fiscal.fingerprint',public.fiscal_command('prevalidate','{"order_id":"fiscal-order"}',gen_random_uuid())->>'fingerprint',true);
select set_config('fiscal.operation',gen_random_uuid()::text,true);
select set_config('fiscal.doc',public.fiscal_command('request',jsonb_build_object('order_id','fiscal-order','fingerprint',current_setting('fiscal.fingerprint')),current_setting('fiscal.operation')::uuid)->>'id',true);
select is(public.fiscal_command('request',jsonb_build_object('order_id','fiscal-order','fingerprint',current_setting('fiscal.fingerprint')),current_setting('fiscal.operation')::uuid)->>'id',current_setting('fiscal.doc'),'retry returns same document');
select is(public.fiscal_command('request',jsonb_build_object('order_id','fiscal-order','fingerprint',current_setting('fiscal.fingerprint')),gen_random_uuid())->>'id',current_setting('fiscal.doc'),'double click with another key still reuses active full-order document');
select is((select count(*)::integer from public.fiscal_documents),1,'only one document');
select set_config('fiscal.external',(select external_id from public.fiscal_documents where id=current_setting('fiscal.doc')::uuid),true);
select set_config('fiscal.snapshot',(select snapshot::text from public.fiscal_documents where id=current_setting('fiscal.doc')::uuid),true);
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external'),'event_id','fiscal-processing','sequence',1,'state','processing'))->>'result','applied','provider processing accepted');
select is(public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external'),'event_id','fiscal-authorized','sequence',2,'state','authorized_qa'))->>'result','applied','provider confirms only QA authorization and system audit succeeds');
select is(public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external'),'event_id','fiscal-authorized','sequence',2,'state','authorized_qa'))->>'result','duplicate','valid replay idempotent');
select throws_ok($$select public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external'),'event_id','fiscal-authorized','sequence',3,'state','cancelled_qa'))$$,'P0001','Fiscal event identity mismatch','event identity reuse rejected');
select is(public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external'),'event_id','fiscal-old','sequence',1,'state','processing'))->>'result','stale','old event cannot revert authorization');
reset role;
select set_config('request.jwt.claims','{"sub":"d1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
update public.customers set name='Changed customer' where id='fiscal-customer';
update public.products set name='Changed product' where id='fiscal-product';
select is((select snapshot::text from public.fiscal_documents where id=current_setting('fiscal.doc')::uuid),current_setting('fiscal.snapshot'),'canonical changes preserve snapshot');
select is(public.fiscal_source(null)#>>'{rows,0,customer_name}','Synthetic fiscal customer','document list preserves historical customer name');
select throws_ok($$update public.fiscal_documents set snapshot='{}' where id=current_setting('fiscal.doc')::uuid$$,'P0001','Fiscal snapshot is immutable','snapshot direct overwrite rejected');
set local role authenticated;
select throws_ok($$select public.fiscal_command('cancel_prepare',jsonb_build_object('id',current_setting('fiscal.doc'),'reason','short'),gen_random_uuid())$$,'22023','Fiscal: Motivo deve ter entre 15 e 250 caracteres.','invalid reason blocked');
select public.fiscal_command('cancel_prepare',jsonb_build_object('id',current_setting('fiscal.doc'),'reason','Cancelamento sintético de teste QA'),gen_random_uuid());
select is((select status from public.fiscal_documents where id=current_setting('fiscal.doc')::uuid),'authorized_qa','local cancel request does not cancel document');
reset role;
update public.fiscal_documents set issued_at=now()-interval '25 hours' where id=current_setting('fiscal.doc')::uuid;
set local role authenticated;
select is(public.fiscal_command('cancel_prepare',jsonb_build_object('id',current_setting('fiscal.doc'),'reason','Cancelamento sintético de teste QA'),gen_random_uuid())->>'id',current_setting('fiscal.doc'),'pending cancellation retry survives elapsed request window');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external'),'event_id','fiscal-cancel-reject','sequence',3,'state','cancel_rejected'));
reset role;
select is((select status from public.fiscal_documents where id=current_setting('fiscal.doc')::uuid),'authorized_qa','provider cancellation rejection preserves authorized state');
select set_config('request.jwt.claims','{"sub":"d1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.fiscal_command('cancel_prepare',jsonb_build_object('id',current_setting('fiscal.doc'),'reason','Cancelamento sintético de teste QA'),gen_random_uuid())$$,'22023','Fiscal: Cancelamento QA indisponível; prazo de teste de 24 horas ou status inválido.','new cancellation outside QA window rejected');
reset role;
update public.fiscal_documents set issued_at=now() where id=current_setting('fiscal.doc')::uuid;
select set_config('request.jwt.claims','{"sub":"d1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.fiscal_command('cancel_prepare',jsonb_build_object('id',current_setting('fiscal.doc'),'reason','Repetição de cancelamento sintético QA'),gen_random_uuid());
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external'),'event_id','fiscal-cancel','sequence',4,'state','cancelled_qa'));
reset role;
select is((select status from public.fiscal_documents where id=current_setting('fiscal.doc')::uuid),'cancelled_qa','provider cancellation confirmed');
select ok((select protocol is not null and cancellation_protocol is not null and number is not null and access_key is null from public.fiscal_documents where id=current_setting('fiscal.doc')::uuid),'QA references preserved without fake access key');
select is((select count(*)::integer from public.financial_transactions where company_id=current_setting('fiscal.company')),0,'fiscal creates no financial revenue or payment');
select is((select status from public.orders where id='fiscal-order'),'aguardando_pagamento','fiscal never changes operational status');
select set_config('request.jwt.claims','{"sub":"d1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select set_config('fiscal.doc2',public.fiscal_command('request',jsonb_build_object('order_id','fiscal-order2','fingerprint',public.fiscal_command('prevalidate','{"order_id":"fiscal-order2"}',gen_random_uuid())->>'fingerprint'),gen_random_uuid())->>'id',true);
reset role;
select set_config('fiscal.external2',(select external_id from public.fiscal_documents where id=current_setting('fiscal.doc2')::uuid),true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external2'),'event_id','fiscal-processing2','sequence',1,'state','processing'));
select public.fiscal_provider_event(jsonb_build_object('external_id',current_setting('fiscal.external2'),'event_id','fiscal-reject2','sequence',2,'state','rejected'));
reset role;
select is((select status from public.fiscal_documents where id=current_setting('fiscal.doc2')::uuid),'rejected','provider rejection stored with sanitized message');
select set_config('request.jwt.claims','{"sub":"d1100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::integer from public.fiscal_documents),0,'other tenant cannot read documents');
select throws_ok($$select public.fiscal_command('prevalidate','{"order_id":"fiscal-order"}',gen_random_uuid())$$,'42501','Fiscal denied','other tenant cannot prepare document');
reset role;
select set_config('request.jwt.claims','{"sub":"d1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into public.role_permissions(company_id,path,roles) values(current_setting('fiscal.company'),'/financial','{}') on conflict(company_id,path) do update set roles='{}';
set local role authenticated;
select throws_ok($$select public.fiscal_source(null)$$,'42501','Fiscal denied','explicit permission denial respected');
reset role;
select * from finish();
rollback;
